import { finishes } from './model.js';
/** SVG contains only controlled colours and fixed geometry, never arbitrary user text. */
export function plane(finish='pearl',cabin='panorama') {
  const colour=Object.hasOwn(finishes,finish)?finishes[finish]:finishes.pearl;
  const windows=cabin==='quiet'?3:cabin==='flex'?2:6;
  return `<svg viewBox="0 0 720 390" role="img" aria-label="Illustrative solar aircraft top-view schematic"><defs><pattern id="cells" width="17" height="17" patternUnits="userSpaceOnUse"><rect width="17" height="17" fill="#183c51"/><path d="M0 0H17V17" fill="none" stroke="#5c8d9a" stroke-width="1"/></pattern></defs><ellipse cx="360" cy="215" rx="265" ry="100" fill="none" stroke="#7197a5" stroke-dasharray="3 8"/><path d="M347 144L60 265L60 286L351 227L369 227L660 286L660 265L373 144Z" fill="${colour}" stroke="#77919b" stroke-width="2"/><path d="M330 167L109 260L322 216ZM390 167L611 260L398 216Z" fill="url(#cells)"/><path d="M350 283L254 330V344L358 323L466 344V330L370 283Z" fill="${colour}" stroke="#77919b"/><path d="M360 43C331 65 331 123 340 211L351 317Q360 338 369 317L380 211C389 123 389 65 360 43Z" fill="${colour}" stroke="#77919b" stroke-width="2"/><path d="M346 94Q360 78 374 94L375 124Q360 113 345 124Z" fill="#0d3449"/>${Array.from({length:windows},(_,i)=>`<rect x="350" y="${140+i*19}" width="20" height="10" rx="4" fill="#44677a"/>`).join('')}<circle cx="260" cy="245" r="23" fill="none" stroke="#7f9da5"/><circle cx="460" cy="245" r="23" fill="none" stroke="#7f9da5"/><path d="M240 245H280M440 245H480" stroke="#c92036" stroke-width="4"/><g transform="translate(345 276)"><rect width="30" height="18" fill="#10275a"/><path d="M0 0L30 18M30 0L0 18" stroke="white" stroke-width="5"/><path d="M0 0L30 18M30 0L0 18" stroke="#c92036" stroke-width="2"/><path d="M15 0V18M0 9H30" stroke="white" stroke-width="7"/><path d="M15 0V18M0 9H30" stroke="#c92036" stroke-width="4"/></g></svg>`;
}
